<template><ForgeDialog title="Base64 file converter" description="Convert a local file to Base64 or save a Base64 data string as a file." eyebrow="WORKSPACE / CONVERTER" wide @close="emit('close')"><div class="b64-panel"><section><div class="b64-head"><b>File to Base64</b><button class="action-button" @click="choose">Choose file</button></div><input v-model="fileName" readonly placeholder="No file selected" /><textarea :value="encoded" readonly rows="7" placeholder="Base64 output" /><button class="action-button" :disabled="!encoded" @click="copy">Copy Base64</button></section><section><b>Base64 to file</b><textarea v-model="input" rows="7" placeholder="Paste Base64 string" /><button class="primary-button" :disabled="!input.trim()" @click="save">Save file</button></section><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p></div></ForgeDialog></template>
<script setup lang="ts">
import { ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { dialog, fs, clipboard } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const fileName=ref(''); const encoded=ref(''); const input=ref(''); const error=ref(''); const choose=async()=>{const r=await dialog.showOpenDialog({properties:['openFile']});if(r.canceled||!r.filePaths[0])return;fileName.value=r.filePaths[0];try{const text=await fs.readFile(r.filePaths[0]);encoded.value=btoa(unescape(encodeURIComponent(text)))}catch(e){error.value=e instanceof Error?e.message:String(e)}}; const copy=()=>clipboard.writeText(encoded.value); const save=async()=>{const r=await dialog.showSaveDialog({properties:['createDirectory','showOverwriteConfirmation']});if(r.canceled||!r.filePath)return;try{const raw=input.value.replace(/^data:.*?;base64,/,'');await fs.writeBufferBase64(r.filePath,raw)}catch(e){error.value=e instanceof Error?e.message:String(e)}}
</script>
<style scoped>.b64-panel{display:grid;grid-template-columns:1fr 1fr;gap:14px}.b64-panel section{display:grid;gap:9px;align-content:start}.b64-head{display:flex;justify-content:space-between;align-items:center}.b64-panel input,.b64-panel textarea{width:100%;padding:10px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:11px/1.5 var(--pqt-font-mono)}.b64-panel textarea{resize:vertical}</style>
